function aCarta([clase, id, nombre, elemento, ap, propiedades, [es, en], archivo, serie]: Fila): Carta {
  return {
    clase,
    id,
    serie: serie ?? null,
    nombre,
    elemento,
    ap,
    propiedades,
    efecto: { es, en },
    archivo,
  };
}

export const CARTAS: Carta[] = FILAS.map(aCarta);

export const claveDeCarta = (carta: Carta) => `${carta.clase}-${carta.serie ?? ""}-${carta.nombre}`;
export const CARTA_POR_CLAVE = new Map(CARTAS.map((carta) => [claveDeCarta(carta), carta]));
